        assert_eq!(
            names_for(&all, "call_A"),
            vec!["get_weather"],
            "exactly one name-carrying delta per call_id; got {all:?}"
        );
        assert_eq!(args_for(&all, "call_A"), "{\"a\":1}");
    }

    /// SMA-617 §4.1: `output_item.done` for a second item of an already
